import pandas as pd
import numpy as np
import json

# Paso 1: Cargar CSV
df = pd.read_csv('datos.csv', dtype=str, keep_default_na=False)

# Convertir celdas vacías a NaN
for col in df.columns:
    df[col] = df[col].apply(lambda x: np.nan if (isinstance(x, str) and x.strip() == '') else x)

# Paso 2: Deduplicar por id (primera aparición)
df = df.drop_duplicates(subset='id', keep='first').reset_index(drop=True)

# Paso 3: Convertir columnas numéricas (normalizar coma decimal)
num_cols = [col for col in df.columns if col not in ['id', 'region']]

for col in num_cols:
    def convert_to_float(x):
        if pd.isna(x):
            return np.nan
        if isinstance(x, str):
            x = x.strip().replace(',', '.')
        try:
            return float(x)
        except:
            return np.nan

    df[col] = df[col].apply(convert_to_float)

# Paso 4: Seleccionar columnas elegibles (≤20% de ausentes)
total_filas = len(df)
elegibles = [col for col in num_cols if df[col].isna().sum() / total_filas <= 0.20]

# Paso 5: Calcular correlaciones (pairwise complete, máximo |r|)
max_corr = -1
best_pair = None

for i, col_a in enumerate(elegibles):
    for col_b in elegibles[i+1:]:
        mask = df[col_a].notna() & df[col_b].notna()
        if mask.sum() < 2:
            continue

        a_vals = df.loc[mask, col_a].values
        b_vals = df.loc[mask, col_b].values

        try:
            corr = np.corrcoef(a_vals, b_vals)[0, 1]
        except:
            corr = np.nan

        if np.isnan(corr):
            continue

        if abs(corr) > max_corr:
            max_corr = abs(corr)
            best_pair = sorted([col_a, col_b])

# Paso 6 y 7: Calcular medianas, MAD por región y marcar anomalías
anomalies_set = set()

for region in df['region'].unique():
    if pd.isna(region):
        region_df = df[df['region'].isna()]
    else:
        region_df = df[df['region'] == region]

    for col in num_cols:
        vals = region_df[col].dropna()

        if len(vals) == 0:
            continue

        med = vals.median()
        mad = np.median(np.abs(vals - med))

        if mad == 0:
            continue

        escala = 1.4826 * mad
        threshold = 4.5 * escala

        for idx, row in region_df.iterrows():
            val = row[col]
            if pd.isna(val):
                continue

            if abs(val - med) > threshold:
                anomalies_set.add(row['id'])

# Paso 8: Construir e imprimir resultado
anomalies = sorted(list(anomalies_set))

result = {
    "par": best_pair,
    "anomalias": anomalies
}

print(json.dumps(result, ensure_ascii=False))
